    and r.route_type='editorial' and r.status='published';
  if not found then raise exception 'Missing published editorial route krakow/nowa-huta-intro'; end if;
  v_updated := v_updated + 1;

  update public.routes r
  set metadata = jsonb_set(
    coalesce(r.metadata,'{}'::jsonb),
    '{legacy}',
    coalesce(r.metadata->'legacy','{}'::jsonb) || '{"image":"route-rainy-day-krakow.jpg","imageCaption":"Galeria Sztuki Polskiej XIX wieku w Sukiennicach","imageCredit":{"author":"Pudelek (Marcin Szala)","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Galeria_Sztuki_Polskiej_XIX_wieku_w_Sukiennicach_-_sala_Siemiradzkiego.jpg","via":"Wikimedia Commons","quality":"Quality image"}}'::jsonb,
    true
  ), updated_at=now()
  from public.cities c
  where r.city_id=c.id and c.slug='krakow' and r.slug='rainy-day-krakow'
    and r.route_type='editorial' and r.status='published';
  if not found then raise exception 'Missing published editorial route krakow/rainy-day-krakow'; end if;
  v_updated := v_updated + 1;

  if v_updated <> 27 then raise exception 'Route cover sync count mismatch: got %, expected 27',v_updated; end if;
  raise notice 'Route cover metadata synchronized for % editorial routes',v_updated;
end $$;

-- Contract check: every active editorial route now exposes all three cover fields through metadata.legacy.
do $$
declare
  missing_count integer;
begin
  select count(*) into missing_count
  from public.routes r
  join public.cities c on c.id=r.city_id
  where c.status in ('launch','next')
    and r.route_type='editorial' and r.status='published' and r.visibility='public'
    and (
      coalesce(r.metadata->'legacy'->>'image','')=''
      or coalesce(r.metadata->'legacy'->>'imageCaption','')=''
      or r.metadata->'legacy'->'imageCredit' is null
    );
  if missing_count <> 0 then raise exception 'Route cover metadata parity failed: % active editorial routes missing cover fields',missing_count; end if;
end $$;
